extern alias BuilderApp;
using CipherCapsule.Core;
using CipherCapsule.Viewer;
using CipherCapsule.UI;
using System.Reflection;
using Settings113=BuilderApp::CipherCapsule.Builder.Settings;
using Builder113=BuilderApp::CipherCapsule.Builder.BuilderForm;
internal static partial class Program
{
    sealed class InlineProgress<T>(Action<T> report):IProgress<T>{public void Report(T value)=>report(value);}
    static void RunV113()
    {
        string area=Path.Combine(Work,"v113");Directory.CreateDirectory(area);
        foreach(var x in new[]{("動画.mp4","記録映像","記録映像.mp4"),("動画.mp4","記録映像.avi","記録映像.avi.mp4"),("動画.mp4","記録映像.mp4","記録映像.mp4"),("画像.jpg","写真.png","写真.png.jpg"),("文章.txt","メモ","メモ.txt"),("音楽.flac","録音.wav","録音.wav.flac"),("資料.pdf","資料.PDF","資料.PDF"),("圧縮.tar.gz","バックアップ","バックアップ.tar.gz"),("a.tar.bz2","b","b.tar.bz2"),("a.tar.xz","b","b.tar.xz"),("a.tar.zst","b","b.tar.zst"),("a.abc.def","b","b.def"),("README","名前","名前")})
            Test("protected extension "+x.Item1+" -> "+x.Item2,()=>Check(Path.GetFileName(AttachmentNames.SinglePath(Path.Combine(area,x.Item2),x.Item1))==x.Item3));
        Test("filters reflect known unknown composite and absent extensions",()=>{foreach(var name in new[]{"a.pdf","a.txt","a.jpg","a.png","a.flac","a.mp4","a.zip","a.exe","a.abc","a.tar.gz","README"}){using var d=AttachmentNames.Dialog(name);string ext=AttachmentNames.Extension(name);Check(!d.OverwritePrompt&&d.DefaultExt==ext.TrimStart('.')&&d.AddExtension==(ext.Length>0)&&d.Filter.Contains(ext.Length==0?"*.*":"*"+ext));}});
        Test("final path identifies appended overwrite target",()=>{string final=Path.Combine(area,"上書き.avi.mp4");File.WriteAllText(final,"KEEP");string raw=Path.Combine(area,"上書き.avi");Check(!File.Exists(raw)&&AttachmentNames.SinglePath(raw,"a.mp4")==final&&File.ReadAllText(final)=="KEEP");});
        Test("invalid final names directories devices and traversal rejected",()=>{foreach(string n in new[]{"CON","NUL.txt","a.","a ","a:b","a|b"})Reject(()=>AttachmentNames.SinglePath(Path.Combine(area,n),"a.pdf"));Reject(()=>AttachmentNames.SinglePath("relative.txt","a.pdf"));string dir=Path.Combine(area,"directory.pdf");Directory.CreateDirectory(dir);Reject(()=>AttachmentNames.SinglePath(dir,"a.pdf"));Reject(()=>AttachmentNames.Available(area,"../outside.txt",new(StringComparer.OrdinalIgnoreCase)));});
        Test("collision numbers start at 2 and preserve compound extension",()=>{var names=new HashSet<string>(["archive.tar.gz","archive (2).tar.gz","README"],StringComparer.OrdinalIgnoreCase);Check(Path.GetFileName(AttachmentNames.Available(area,"archive.tar.gz",names))=="archive (3).tar.gz");Check(Path.GetFileName(AttachmentNames.Available(area,"README",names))=="README (2)");Check(Path.GetFileName(AttachmentNames.Available(area,"ARCHIVE.TAR.GZ",names))=="ARCHIVE (4).TAR.GZ");});
        Test("long collision name rejected without truncation",()=>{string name=new string('a',251)+".txt";Reject(()=>AttachmentNames.Available(area,name,new([name],StringComparer.OrdinalIgnoreCase)));});
        string one=Path.Combine(area,"資料.pdf"),dir2=Path.Combine(area,"別"),dir3=Path.Combine(area,"大小");Directory.CreateDirectory(dir2);Directory.CreateDirectory(dir3);
        File.WriteAllText(one,"PDF dummy 日本語",Limits.Utf8);string two=Path.Combine(dir2,"資料.pdf");File.WriteAllText(two,"SECOND",Limits.Utf8);string three=Path.Combine(dir3,"資料.PDF");File.WriteAllText(three,"CASE",Limits.Utf8);
        string tar=Path.Combine(area,"archive.tar.gz"),plain=Path.Combine(area,"README");File.WriteAllText(tar,"COMPOUND");File.WriteAllText(plain,"NO EXT");
        string pack=Path.Combine(area,"batch.exe");Gen(pack,"一括保存",BodyKind.TEXT,[one,two,three,tar,plain]);
        using var c=Unlock(pack);
        Test("batch authentication failure retains prior verified file without partial output",()=>{
            string changed=Repack(pack,"v113-auth-corrupt",(m,f,start)=>{var a=m.Attachments[1];f.Position=start+a.Offset+30;int b=f.ReadByte();f.Position--;f.WriteByte((byte)(b^1));f.Position=start+a.Offset;a.Sha256=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Container.Read(f,(int)a.CipherLength)));});
            using var damaged=Unlock(changed);string folder=Path.Combine(area,"authentication-failure");Directory.CreateDirectory(folder);var r=AttachmentBatch.Save(damaged,folder,default);Check(r.Succeeded==1&&r.Failed==1&&r.Unprocessed==3&&Hash(r.Saved[0].Path)==Hash(one)&&!File.Exists(Path.Combine(folder,"資料 (2).pdf"))&&!Directory.EnumerateFiles(folder,".cc-*.tmp").Any());
        });
        Test("real bulk save preserves originals directories duplicates and SHA256",()=>{string folder=Path.Combine(area,"batch-out");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"資料.pdf"),"KEEP");Directory.CreateDirectory(Path.Combine(folder,"資料 (2).pdf"));File.WriteAllText(Path.Combine(folder,"archive.tar.gz"),"KEEP TAR");var result=AttachmentBatch.Save(c,folder,default);Check(result.Succeeded==5&&result.Failed==0&&result.Unprocessed==0);Check(result.Saved.Select(s=>Path.GetFileName(s.Path)).SequenceEqual(new[]{"資料 (3).pdf","資料 (4).pdf","資料 (5).PDF","archive (2).tar.gz","README"}));string[] inputs=[one,two,three,tar,plain];for(int i=0;i<inputs.Length;i++)Check(Hash(result.Saved[i].Path)==Hash(inputs[i]));Check(File.ReadAllText(Path.Combine(folder,"資料.pdf"))=="KEEP"&&File.ReadAllText(Path.Combine(folder,"archive.tar.gz"))=="KEEP TAR");});
        Test("zero attachments no file writes and bulk button disabled",()=>{string f=Path.Combine(area,"empty.exe"),folder=Path.Combine(area,"empty-out");Directory.CreateDirectory(folder);Gen(f,"empty",BodyKind.TEXT,[]);using var cc=Unlock(f);using var viewer=new ViewerForm(cc);Check(!Field<Button>(viewer,"saveAll").Enabled);var r=AttachmentBatch.Save(cc,folder,default);Check(r.Succeeded==0&&r.Failed==0&&r.Unprocessed==0&&!Directory.EnumerateFileSystemEntries(folder).Any());});
        Test("one attachment batch real save and hash",()=>{string f=Path.Combine(area,"one.exe"),folder=Path.Combine(area,"one-out");Directory.CreateDirectory(folder);Gen(f,"one",BodyKind.TEXT,[one]);using var cc=Unlock(f);var r=AttachmentBatch.Save(cc,folder,default);Check(r.Succeeded==1&&Hash(r.Saved[0].Path)==Hash(one));});
        Test("cancellation before first file makes no files",()=>{string folder=Path.Combine(area,"cancel-before");Directory.CreateDirectory(folder);using var ct=new CancellationTokenSource();ct.Cancel();var r=AttachmentBatch.Save(c,folder,ct.Token);Check(r.Canceled&&r.Succeeded==0&&r.Failed==0&&r.Unprocessed==5&&!Directory.EnumerateFiles(folder).Any());});
        Test("cancel after first success preserves completed file only",()=>{string folder=Path.Combine(area,"cancel-between");Directory.CreateDirectory(folder);using var ct=new CancellationTokenSource();var r=AttachmentBatch.Save(c,folder,ct.Token,new InlineProgress<BatchProgress>(p=>{if(p.Completed==1)ct.Cancel();}));Check(r.Canceled&&r.Succeeded==1&&r.Unprocessed==4&&Directory.EnumerateFiles(folder).Count()==1&&Hash(r.Saved[0].Path)==Hash(one));});
        Test("external name race stops without overwrite and keeps prior success",()=>{string folder=Path.Combine(area,"race");Directory.CreateDirectory(folder);var r=AttachmentBatch.Save(c,folder,default,new InlineProgress<BatchProgress>(p=>{if(p.Completed==1&&p.Current=="資料.pdf")File.WriteAllText(Path.Combine(folder,"資料 (2).pdf"),"EXTERNAL");}));Check(r.Succeeded==1&&r.Failed==1&&r.Unprocessed==3&&File.ReadAllText(Path.Combine(folder,"資料 (2).pdf"))=="EXTERNAL"&&Hash(r.Saved[0].Path)==Hash(one)&&!Directory.EnumerateFiles(folder,".cc-*.tmp").Any());});
        Test("cancel during actual multi-chunk save removes partial only",()=>{string big=Path.Combine(area,"large.bin");File.WriteAllBytes(big,new byte[8*1024*1024]);string f=Path.Combine(area,"cancel-mid.exe"),folder=Path.Combine(area,"cancel-mid");Directory.CreateDirectory(folder);Gen(f,"cancel",BodyKind.TEXT,[one,big]);using var cc=Unlock(f);using var ct=new CancellationTokenSource();var r=AttachmentBatch.Save(cc,folder,ct.Token,new InlineProgress<BatchProgress>(p=>{if(p.Current=="large.bin"&&p.BytesDone>new FileInfo(one).Length)ct.Cancel();}));Check(r.Canceled&&r.Succeeded==1&&r.Unprocessed==1&&Hash(r.Saved[0].Path)==Hash(one)&&!File.Exists(Path.Combine(folder,"large.bin"))&&!Directory.EnumerateFiles(folder,".cc-*.tmp").Any());});
        Test("bulk UI buttons fit 9 12 17 and prevent concurrent saves",()=>{using var viewer=new ViewerForm(c);viewer.Show();foreach(int size in new[]{9,12,17}){viewer.SetSize(size);viewer.PerformLayout();var buttons=AllControls(viewer).OfType<Button>().ToArray();foreach(var b in buttons)Check(b.Width>=TextRenderer.MeasureText(b.Text,b.Font).Width);foreach(var b in buttons)foreach(var other in buttons.Where(x=>x!=b&&x.Parent==b.Parent))Check(!b.Bounds.IntersectsWith(other.Bounds));}var set=typeof(ViewerForm).GetMethod("SetSaving",BindingFlags.Instance|BindingFlags.NonPublic)!;set.Invoke(viewer,[true]);Check(!Field<Button>(viewer,"save").Enabled&&!Field<Button>(viewer,"saveAll").Enabled&&Field<Button>(viewer,"cancel").Enabled);set.Invoke(viewer,[false]);viewer.Close();});
        Test("read-only dialog starts unselected at beginning then keeps selection and copy",()=>{using var f=new ReadOnlyDialog("試験",string.Join("\r\n",Enumerable.Range(0,100).Select(i=>"行 "+i)),new Size(900,520),true);f.Shown+=(_,_)=>{Check(f.Content.ReadOnly&&f.Content.SelectionStart==0&&f.Content.SelectionLength==0&&f.Content.GetCharIndexFromPosition(Point.Empty)==0&&f.ActiveControl==f.CloseButton);f.Content.Focus();Check(f.Content.SelectionLength==0);f.Content.SelectAll();Check(f.Content.SelectedText==f.Content.Text&&f.Content.ShortcutsEnabled);f.Content.Copy();Check(Clipboard.GetText()==f.Content.Text);f.Close();};Application.Run(f);});
        string ini=Path.Combine(AppContext.BaseDirectory,"CipherCapsule.ini");byte[]? prior=File.Exists(ini)?File.ReadAllBytes(ini):null;
        string previous="[Window]\nX=151\nY=171\nWidth=1280\nHeight=1080\nFont=17\nKind=1\nPasswordRevealed=1\n";
        try{
            Test("old v112 INI preserves all values and defaults directory",()=>{File.WriteAllText(ini,previous);var s=Settings113.Load();Check(s.Font==17&&s.X==151&&s.Kind==1&&s.PasswordRevealed&&s.LastOutputDirectory==Settings113.Documents);});
            string unicode=Path.Combine(area,"保存先 日本語🔑=equal");Directory.CreateDirectory(unicode);
            Test("Unicode spaces and equals folder survives atomic save reload",()=>{var s=Settings113.Load();s.LastOutputDirectory=unicode;s.Save();var r=Settings113.Load();Check(r.LastOutputDirectory==unicode&&r.Font==17&&r.Kind==1&&r.PasswordRevealed);});
            Test("bad duplicate or missing output folder does not reset old values",()=>{foreach(var value in new[]{"relative", "Z:\\missing-v113-folder", "",unicode+"\nLastOutputDirectory=bad","bad\0value"}){File.WriteAllText(ini,previous+"LastOutputDirectory="+value+"\n");var s=Settings113.Load();Check(s.X==151&&s.Font==17&&s.Kind==1&&s.PasswordRevealed&&s.LastOutputDirectory==Settings113.Documents);}});
            Test("Builder dialog uses successful in-memory directory and retains default name",()=>{File.WriteAllText(ini,previous+"LastOutputDirectory="+unicode+"\n");using var b=new Builder113();var method=typeof(Builder113).GetMethod("CreateSaveDialog",BindingFlags.Instance|BindingFlags.NonPublic)!;using var d=(SaveFileDialog)method.Invoke(b,null)!;Check(d.InitialDirectory==unicode&&d.FileName=="SecureMessage.exe");Check(Field<string>(b,"lastOutputDirectory")==unicode);});
            Test("missing stored directory falls back without discarding other settings",()=>{Directory.Delete(unicode);var r=Settings113.Load();Check(r.LastOutputDirectory==Settings113.Documents&&r.PasswordRevealed&&r.Font==17);});
        }finally{if(prior!=null)File.WriteAllBytes(ini,prior);else File.Delete(ini);}
    }
}
